from __future__ import annotations

import hashlib
import json
import os
import tempfile
from dataclasses import dataclass
from pathlib import Path
from typing import Any


class ShadowInvariantError(RuntimeError):
    pass


class ImmutableRawArchive:
    """Hash-addressed local raw archive. No networking and no mutable overwrite path."""

    def __init__(self, root: Path):
        self.root = Path(root)

    def store_bytes(self, payload: bytes, *, source: str, received_at: str, content_type: str | None = None) -> dict[str, Any]:
        if not isinstance(payload, (bytes, bytearray)):
            raise ShadowInvariantError("payload must be bytes")
        raw = bytes(payload)
        digest = hashlib.sha256(raw).hexdigest()
        obj = self.root / "objects" / digest[:2] / f"{digest}.bin"
        manifest = self.root / "manifests" / f"{digest}.json"
        obj.parent.mkdir(parents=True, exist_ok=True)
        manifest.parent.mkdir(parents=True, exist_ok=True)

        if obj.exists():
            if obj.read_bytes() != raw:
                raise ShadowInvariantError("hash-addressed object mutation detected")
        else:
            fd, tmp_name = tempfile.mkstemp(prefix=f".{digest}.", suffix=".tmp", dir=str(obj.parent))
            try:
                with os.fdopen(fd, "wb") as handle:
                    handle.write(raw)
                    handle.flush()
                    os.fsync(handle.fileno())
                os.replace(tmp_name, obj)
            finally:
                try:
                    os.unlink(tmp_name)
                except FileNotFoundError:
                    pass

        record = {
            "schema": "HENGELTJE_IMMUTABLE_RAW_V1",
            "sha256": digest,
            "bytes": len(raw),
            "source": source,
            "received_at": received_at,
            "content_type": content_type,
            "object_name": obj.name,
        }
        encoded = (json.dumps(record, sort_keys=True, separators=(",", ":")) + "\n").encode("utf-8")
        if manifest.exists():
            if manifest.read_bytes() != encoded:
                raise ShadowInvariantError("manifest mutation detected for existing raw object")
        else:
            fd, tmp_name = tempfile.mkstemp(prefix=f".{digest}.", suffix=".tmp", dir=str(manifest.parent))
            try:
                with os.fdopen(fd, "wb") as handle:
                    handle.write(encoded)
                    handle.flush()
                    os.fsync(handle.fileno())
                os.replace(tmp_name, manifest)
            finally:
                try:
                    os.unlink(tmp_name)
                except FileNotFoundError:
                    pass
        return record


@dataclass(frozen=True)
class VirtualOrder:
    ticker: str
    side: str
    price_cents: int
    size_contracts: int
    t_minus_minutes: int
    created_at: str

    def __post_init__(self) -> None:
        if self.side not in {"YES", "NO"}:
            raise ShadowInvariantError("invalid side")
        if not 1 <= self.price_cents <= 99:
            raise ShadowInvariantError("invalid passive price")
        if self.size_contracts <= 0:
            raise ShadowInvariantError("invalid size")


@dataclass
class QueueTracker:
    order: VirtualOrder
    queue_ahead: int = 0
    proven_fill: int = 0
    last_sequence: int | None = None
    status: str = "AWAITING_SNAPSHOT"

    @property
    def remaining(self) -> int:
        return max(0, self.order.size_contracts - self.proven_fill)

    def snapshot(self, *, sequence: int, displayed_qty_at_price: int) -> None:
        if sequence < 0 or displayed_qty_at_price < 0:
            raise ShadowInvariantError("invalid snapshot")
        if self.last_sequence is not None:
            raise ShadowInvariantError("snapshot reset forbidden for active order")
        self.last_sequence = sequence
        self.queue_ahead = displayed_qty_at_price
        self.status = "ACTIVE"

    def event(self, *, sequence: int, executed_qty: int = 0, cancelled_qty: int = 0, touched: bool = False) -> None:
        if self.status != "ACTIVE":
            return
        if self.last_sequence is None or sequence != self.last_sequence + 1:
            self.status = "UNPROVEN_FILL"
            return
        if executed_qty < 0 or cancelled_qty < 0:
            raise ShadowInvariantError("negative event quantity")
        self.last_sequence = sequence
        # Touches and cancellations intentionally receive zero queue-depletion credit.
        _ = touched, cancelled_qty
        if executed_qty == 0:
            return
        consumed_ahead = min(self.queue_ahead, executed_qty)
        self.queue_ahead -= consumed_ahead
        residual_execution = executed_qty - consumed_ahead
        if residual_execution > 0 and self.remaining > 0:
            self.proven_fill += min(self.remaining, residual_execution)

    def reconnect(self, *, continuity_proven: bool = False) -> None:
        if self.status == "ACTIVE" and not continuity_proven:
            self.status = "UNPROVEN_FILL"

    def restart(self, *, continuity_proven: bool = False) -> None:
        if self.status == "ACTIVE" and not continuity_proven:
            self.status = "UNPROVEN_RESTART"

    def primary_filled_quantity(self) -> int:
        if self.status in {"UNPROVEN_FILL", "UNPROVEN_RESTART"}:
            return 0
        return self.proven_fill
